(()=>{
 const style=document.createElement('style');style.textContent=`#productReviews h3{font:600 1.5rem Georgia,serif;margin-bottom:12px}#reviewForm{padding:20px;margin-top:20px;background:#f6f2e9;border:1px solid #e3dacb;border-radius:18px}#reviewForm fieldset{padding:0;margin:0;border:0}#reviewForm legend{font-weight:700;font-size:.9rem;margin-bottom:10px}.review-stars{display:flex;gap:6px}.review-star{position:relative;cursor:pointer}.review-star input{position:absolute;opacity:0;width:1px;height:1px}.review-star span{display:grid;place-items:center;width:46px;height:48px;border:1px solid #ded6c8;border-radius:12px;background:white;color:#c4bcac;font-size:32px;transition:color .15s,background .15s}.review-star.selected span{color:#ad791c;background:#fff0cb;border-color:#d6ac57}.review-star input:focus-visible+span{outline:3px solid var(--forest);outline-offset:3px}.review-star:hover span{border-color:#ad791c}.review-rating-label{font-size:.85rem;color:var(--muted);min-height:24px;margin:10px 0 16px}#reviewForm textarea{font:inherit;min-height:120px;line-height:1.6}#reviewForm .btn{width:100%;border:0;background:var(--forest);color:white;border-radius:999px;padding:13px;font-weight:700;margin-top:12px}#reviewForm .btn:disabled{opacity:.6}#productReviews article{padding:16px!important;border:1px solid var(--line)!important;border-radius:14px;margin:12px 0;background:#fffdf9}#productReviews article>span{display:block;color:#ad791c;letter-spacing:2px;margin:8px 0}#productReviews article small{color:#376446!important}#reviewMessage{color:#984528;font-size:.85rem}@media(max-width:420px){#reviewForm{padding:16px}.review-star span{width:42px;height:46px}.review-stars{gap:5px}}`;document.head.append(style);
 function upgradeRating(){const select=document.querySelector('#reviewRating');if(!select||select.tagName!=='SELECT')return;const field=select.closest('.field'),fieldset=document.createElement('fieldset');fieldset.innerHTML=`<legend>Beri rating produk</legend><div class="review-stars">${[1,2,3,4,5].map(value=>`<label class="review-star"><input type="radio" name="reviewStars" value="${value}" required aria-label="${value} dari 5 bintang"><span aria-hidden="true">★</span></label>`).join('')}</div><p class="review-rating-label" role="status">Ketuk bintang untuk memilih rating.</p><input type="hidden" id="reviewRating" value="">`;field.replaceWith(fieldset);const names=['','Sangat kurang','Kurang','Cukup','Bagus','Sangat bagus'];fieldset.querySelectorAll('input[type=radio]').forEach(input=>input.addEventListener('change',()=>{const rating=Number(input.value);fieldset.querySelector('#reviewRating').value=input.value;fieldset.querySelectorAll('.review-star').forEach((label,index)=>label.classList.toggle('selected',index<rating));fieldset.querySelector('.review-rating-label').textContent=`${rating} dari 5 — ${names[rating]}`}));const textarea=document.querySelector('#reviewComment');textarea.placeholder='Bagaimana kualitas dan kenyamanan produknya?'}
 style.textContent+=' .review-star span{border:0;border-radius:0;background:transparent;font-size:38px}.review-star.selected span{background:transparent;color:#ad791c}.review-star:hover span{color:#ad791c}.review-star input:focus-visible+span{outline-offset:0;border-radius:6px}';
 const box=document.createElement('section');box.id='productReviews';box.style.cssText='margin-top:22px;padding-top:18px;border-top:1px solid var(--line)';document.querySelector('#detailDescription').parentElement.append(box);
 new MutationObserver(upgradeRating).observe(box,{childList:true,subtree:true});
 const base=openDetail;openDetail=function(id){base(id);loadReviews(id)};
 let requestVersion=0;
 async function loadReviews(id){const version=++requestVersion;box.textContent='Memuat ulasan…';try{const response=await fetch(`/api/products/${id}/reviews`,{cache:'no-store'}),data=await response.json();if(version!==requestVersion)return;if(!response.ok)throw new Error(data.error||'Ulasan belum tersedia');box.innerHTML=`<h3>Rating dan ulasan</h3><p>${data.summary.count?`★ ${data.summary.average}/5 · ${data.summary.count} ulasan`:'Belum ada ulasan.'}</p>${data.reviews.map(item=>`<article style="border-top:1px solid var(--line);padding:12px 0"><strong>${escapeAttr(item.customerName)}</strong> · <span aria-label="${item.rating} dari 5 bintang">${'★'.repeat(item.rating)}${'☆'.repeat(5-item.rating)}</span><small style="display:block;color:var(--muted)">Pembelian terverifikasi</small><p style="white-space:pre-wrap;overflow-wrap:anywhere">${escapeAttr(item.comment)}</p></article>`).join('')}${data.eligible?'<form id="reviewForm"><div class="field"><label for="reviewRating">Beri rating</label><select id="reviewRating" required><option value="">Pilih bintang</option><option value="5">★★★★★ — 5</option><option value="4">★★★★☆ — 4</option><option value="3">★★★☆☆ — 3</option><option value="2">★★☆☆☆ — 2</option><option value="1">★☆☆☆☆ — 1</option></select></div><div class="field"><label for="reviewComment">Ulasan Anda</label><textarea id="reviewComment" minlength="5" maxlength="1000" required></textarea></div><p id="reviewMessage" role="status"></p><button class="btn" type="submit">Kirim ulasan</button></form>':`<p class="meta">${data.alreadyReviewed?'Anda sudah memberi ulasan untuk produk ini.':data.loggedIn?'Anda dapat memberi ulasan setelah pesanan produk ini selesai.':'Masuk ke akun pelanggan untuk memberi ulasan setelah pesanan selesai.'}</p>`}`;const form=box.querySelector('#reviewForm');if(form)form.addEventListener('submit',async event=>{event.preventDefault();const button=event.submitter;button.disabled=true;try{const response=await fetch(`/api/products/${id}/reviews`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({rating:Number(form.querySelector('#reviewRating').value),comment:form.querySelector('#reviewComment').value})}),data=await response.json();if(!response.ok)throw new Error(data.error);await loadReviews(id)}catch(error){form.querySelector('#reviewMessage').textContent=error.message;button.disabled=false}})}catch(error){if(version===requestVersion)box.textContent=error.message}}
 style.textContent+=' #productReviews:has(article)>h3+p::first-letter{color:#ad791c}';
})();
